pub mod rgb;
pub mod converter;
pub mod fmt;

/// RGB color with C++ `float` (f32) channels.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct RGB {
    pub r: f32,
    pub g: f32,
    pub b: f32,
}

impl RGB {
    pub fn new(r: f32, g: f32, b: f32) -> RGB {
        RGB { r, g, b }
    }
}

use crate::rgb::RGB;

/// Color conversions mirroring the C++ `ColorConverter`.
/// All arithmetic is done in f32, exactly like the original C++ floats.
pub struct ColorConverter;

impl ColorConverter {
    /// Each channel becomes `1.0 - c`.
    pub fn invert(color: RGB) -> RGB {
        RGB::new(1.0 - color.r, 1.0 - color.g, 1.0 - color.b)
    }

    /// Rec.709 luma, computed in f32, summed left-to-right:
    /// 0.2126*r + 0.7152*g + 0.0722*b, assigned to all three channels.
    pub fn grayscale(color: RGB) -> RGB {
        let luma = 0.2126_f32 * color.r + 0.7152_f32 * color.g + 0.0722_f32 * color.b;
        RGB::new(luma, luma, luma)
    }
}

/// Formats a C++ `float` the way `std::cout` does by default:
/// printf `%g` with precision 6, applied to the value promoted to double.
///
/// Rules of `%g` with precision P=6:
/// - Round the value to P significant digits (round-half-to-even).
/// - Let X be the decimal exponent of the rounded value.
/// - If -4 <= X < P, use fixed notation with precision P-1-X, then strip
///   trailing fraction zeros (and a bare trailing '.').
/// - Otherwise use scientific notation `d.ddde±XX` with trailing mantissa
///   zeros stripped and the exponent zero-padded to at least 2 digits.
/// - Zero prints as `0`.
pub fn format_g(value: f32) -> String {
    let v = value as f64;
    if v == 0.0 {
        // Covers +0.0 and -0.0 (printf %g prints "-0" for negative zero,
        // but the reference program never produces it; cout of -0.0f is
        // "-0". Handle it for completeness.)
        return if value.is_sign_negative() { "-0".to_string() } else { "0".to_string() };
    }
    if !v.is_finite() {
        // Match glibc: "inf" / "-inf" / "nan".
        return if v.is_nan() {
            "nan".to_string()
        } else if v > 0.0 {
            "inf".to_string()
        } else {
            "-inf".to_string()
        };
    }

    let negative = v < 0.0;
    let abs = v.abs();

    // Round to 6 significant digits via scientific formatting.
    // Rust's {:.*e} is correctly rounded (round-half-to-even), same as glibc.
    let sci = format!("{:.5e}", abs); // e.g. "2.12600e-5"
    let (mantissa_str, exp_str) = sci.split_once('e').unwrap();
    let exponent: i32 = exp_str.parse().unwrap();
    // 6 significant digits, no dot: e.g. "212600"
    let digits: String = mantissa_str.chars().filter(|c| c.is_ascii_digit()).collect();
    debug_assert_eq!(digits.len(), 6);

    let body = if (-4..6).contains(&exponent) {
        format_fixed(&digits, exponent)
    } else {
        format_scientific(&digits, exponent)
    };

    if negative {
        format!("-{}", body)
    } else {
        body
    }
}

/// Fixed notation from 6 significant digits and decimal exponent X.
/// Value = 0.d1 d2 ... d6 * 10^(X+1), i.e. digits[0] is at place 10^X.
fn format_fixed(digits: &str, exponent: i32) -> String {
    let mut s = String::new();
    if exponent >= 0 {
        // digits before the decimal point: exponent+1 of them
        let int_len = (exponent + 1) as usize;
        s.push_str(&digits[..int_len]);
        let frac = &digits[int_len..];
        let frac = frac.trim_end_matches('0');
        if !frac.is_empty() {
            s.push('.');
            s.push_str(frac);
        }
    } else {
        // 0.000ddd style: -exponent-1 leading zeros after the point
        s.push_str("0.");
        for _ in 0..(-exponent - 1) {
            s.push('0');
        }
        let frac = digits.trim_end_matches('0');
        s.push_str(frac);
    }
    s
}

/// Scientific notation: d.ddde±XX, mantissa trailing zeros stripped,
/// exponent zero-padded to at least 2 digits.
fn format_scientific(digits: &str, exponent: i32) -> String {
    let mut s = String::new();
    s.push_str(&digits[..1]);
    let frac = digits[1..].trim_end_matches('0');
    if !frac.is_empty() {
        s.push('.');
        s.push_str(frac);
    }
    s.push('e');
    if exponent < 0 {
        s.push('-');
    } else {
        s.push('+');
    }
    let abs_exp = exponent.abs();
    if abs_exp < 10 {
        s.push('0');
    }
    s.push_str(&abs_exp.to_string());
    s
}

#[path = "src/lib.rs"]
mod color;

use color::converter::ColorConverter;
use color::fmt::format_g;
use color::rgb::RGB;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut r: f32 = 0.3;
    let mut g: f32 = 0.7;
    let mut b: f32 = 0.2;
    if args.len() > 3 {
        r = args[1].parse::<f32>().unwrap();
        g = args[2].parse::<f32>().unwrap();
        b = args[3].parse::<f32>().unwrap();
    }
    let rgb = RGB::new(r, g, b);
    let inverted = ColorConverter::invert(rgb);
    let grayscale = ColorConverter::grayscale(rgb);
    println!(
        "{} {} {} {} {} {}",
        format_g(inverted.r),
        format_g(inverted.g),
        format_g(inverted.b),
        format_g(grayscale.r),
        format_g(grayscale.g),
        format_g(grayscale.b)
    );
}

