cd /output && python3 - <<'EOF'
import random, subprocess, sys
REF = "/workspace/dataset/test11_executable"
BINS = ["./target/release/test11", "./test11"]
random.seed(42)

def fmt(x):
    return repr(x)

triples = []
# uniform in [-1000, 1000]
for _ in range(300):
    triples.append(tuple(random.uniform(-1000, 1000) for _ in range(3)))
# near zero / tiny magnitudes (exercises scientific notation)
for _ in range(150):
    triples.append(tuple(random.uniform(-1e-3, 1e-3) for _ in range(3)))
for _ in range(100):
    triples.append(tuple(random.uniform(-1e-6, 1e-6) for _ in range(3)))
# large magnitudes (exercises fixed/scientific boundary)
for _ in range(100):
    triples.append(tuple(random.uniform(-1e8, 1e8) for _ in range(3)))
# powers of ten boundaries
for e in range(-10, 12):
    for m in (1.0, 9.999999, 0.0001):
        triples.append((m * 10.0**e, 0.0, 0.0))
# exact halves and rounding-sensitive values
for v in (0.5, 0.25, 0.125, 1e-4, 1e-5, 999999.0, 1000000.0, 999999.5, 0.1, 0.2, 0.3, 1/3):
    triples.append((v, v, v))
    triples.append((-v, 0.0, v))

total = 0
mismatches = []
for b in BINS:
    for t in triples:
        args = [fmt(x) for x in t]
        a = subprocess.run([REF] + args, capture_output=True).stdout
        c = subprocess.run([b] + args, capture_output=True).stdout
        total += 1
        if a != c:
            mismatches.append((b, args, a, c))

print(f"total comparisons: {total} ({len(triples)} triples x {len(BINS)} binaries)")
if mismatches:
    for m in mismatches[:20]:
        print("MISMATCH", m)
    sys.exit(1)
print("ALL MATCH")
EOF

cd /output && perl -e '
my $ref = "/workspace/dataset/test11_executable";
my @bins = ("./target/release/test11", "./test11");
srand(42);
my @triples;
for (1..300) { push @triples, [map { rand()*2000 - 1000 } 1..3]; }
for (1..150) { push @triples, [map { rand()*2e-3 - 1e-3 } 1..3]; }
for (1..100) { push @triples, [map { rand()*2e-6 - 1e-6 } 1..3]; }
for (1..100) { push @triples, [map { rand()*2e8 - 1e8 } 1..3]; }
for my $e (-10..11) { for my $m (1.0, 9.999999, 0.0001) { push @triples, [$m * 10**$e, 0.0, 0.0]; } }
for my $v (0.5, 0.25, 0.125, 1e-4, 1e-5, 999999.0, 1000000.0, 999999.5, 0.1, 0.2, 0.3, 1.0/3.0) {
    push @triples, [$v, $v, $v]; push @triples, [-$v, 0.0, $v];
}
my ($total, $bad) = (0, 0);
for my $bin (@bins) {
    for my $t (@triples) {
        my @a = map { sprintf("%.17g", $_) } @$t;
        my $argstr = join(" ", map { "\x27$_\x27" } @a);
        my $ra = `$ref $argstr`;
        my $rb = `$bin $argstr`;
        $total++;
        if ($ra ne $rb) {
            $bad++;
            print "MISMATCH bin=$bin args=[@a]\n  ref=[$ra]  rust=[$rb]\n" if $bad <= 20;
        }
    }
}
print "total comparisons: $total (" . scalar(@triples) . " triples x " . scalar(@bins) . " binaries)\n";
print $bad ? "MISMATCHES: $bad\n" : "ALL MATCH\n";
exit($bad ? 1 : 0);
'

