//! Replica of C++ `std::stof` semantics (glibc strtof underneath).

/// Error kinds matching the C++ exceptions thrown by std::stof.
pub enum StofError {
    InvalidArgument,
    OutOfRange,
}

pub fn stof(s: &str) -> Result<f32, StofError> {
    let bytes = s.as_bytes();
    let mut i = 0;
    // skip leading ASCII whitespace (isspace: space, \t, \n, \v, \f, \r)
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | b'\x0b' | b'\x0c' | b'\r') {
        i += 1;
    }
    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }
    let rest = &s[i..];

    // inf / infinity / nan keywords, case-insensitive
    if let Some(v) = match_keyword(rest) {
        return Ok(if negative { -v } else { v });
    }

    // hex float
    if rest.len() >= 2 && (rest[..2].eq_ignore_ascii_case("0x")) {
        if let Some(v) = parse_hex(&rest[2..]) {
            let v = if negative { -v } else { v };
            return range_check(v);
        }
        // no hex digits after 0x: the value is just "0"
        return Ok(if negative { -0.0 } else { 0.0 });
    }

    // decimal
    if let Some((prefix_len, _)) = scan_decimal(rest) {
        let v: f64 = rest[..prefix_len].parse().unwrap();
        let v = if negative { -v } else { v };
        return range_check(v);
    }

    Err(StofError::InvalidArgument)
}
```

