fn parse_hex(rest: &str) -> Option<f64> {
    let b = rest.as_bytes();
    let mut i = 0;
    let mut mantissa: f64 = 0.0;
    let mut any = false;
    let mut frac_digits = 0i32;
    let mut seen_dot = false;
    while i < b.len() {
        let c = b[i];
        if c == b'.' && !seen_dot {
            seen_dot = true;
            i += 1;
            continue;
        }
        let d = (c as char).to_digit(16);
        match d {
            Some(d) => {
                any = true;
                mantissa = mantissa * 16.0 + d as f64;
                if seen_dot { frac_digits += 1; }
                i += 1;
            }
            None => break,
        }
    }
    if !any { return None; }
    let mut exp: i32 = -4 * frac_digits;
    // optional p exponent
    if i < b.len() && (b[i] == b'p' || b[i] == b'P') {
        let mut j = i + 1;
        let mut esign = 1i32;
        if j < b.len() && (b[j] == b'+' || b[j] == b'-') {
            if b[j] == b'-' { esign = -1; }
            j += 1;
        }
