        float f = strtof(argv[i], &end);
        uint32_t bits;
        memcpy(&bits, &f, 4);
        printf("%-26s end+%-3zd errno=%-3d bits=%08x\n", argv[i], end - argv[i], errno, bits);
    }
    return 0;
}
