args.content:
//! Replica of C++ `std::stof` semantics (glibc `strtof` underneath):
//! lenient longest-prefix parsing plus ERANGE-based `std::out_of_range`.
//!
//! Parsing grammar (longest valid prefix wins, trailing garbage ignored):
//! - leading ASCII whitespace is skipped, then an optional '+'/'-' sign
//! - `inf` / `infinity` / `nan`, case-insensitive
//! - hex floats: `0x` hex digits, optional '.', optional `p`+/-digits binary
//!   exponent (`0x` with no hex digits falls back to matching just `0`)
//! - decimal: digits, optional '.' digits, optional `e`/`E` exponent
//!   (consumed only if digits follow the exponent letter)
//!
//! Range errors (glibc sets ERANGE, `std::stof` throws `std::out_of_range`):
//! - overflow: the value rounds past FLT_MAX to infinity
//! - underflow: the value rounds to zero or into the f32 subnormal range,
//!   unless it is exactly representable there (e.g. `0x1p-127` is fine).
//!
//! Known negligible divergence: for a few adversarial hex inputs with >24
//! significant bits landing within one subnormal ulp of FLT_MIN, glibc's
//! fixed-precision digit collection makes its ERANGE decision depend on
//! nibble-aligned bit truncation (e.g. `0x1.fffffep-127` aborts but
//! `0x1.fffffffp-127` does not, though both round to FLT_MIN). No decimal
//! input and no realistic hex input can hit this.

/// Mirrors the C++ exceptions thrown by `std::stof`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StofError {
    /// `std::invalid_argument`: no valid numeric prefix.
    InvalidArgument,
    /// `std::out_of_range`: ERANGE (overflow or inexact underflow).
    OutOfRange,
}

/// Parses `s` like C++ `std::stof`.
pub fn stof(s: &str) -> Result<f32, StofError> {
    let b = s.as_bytes();
    let mut i = 0;
    // isspace(): space, \t, \n, \v, \f, \r
    while i < b.len() && matches!(b[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }
    let mut negative = false;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        negative = b[i] == b'-';
        i += 1;
    }
    let rest = &s[i..];

    // inf / infinity / nan keywords, case-insensitive. These never set ERANGE.
    if let Some(v) = match_keyword(rest) {
        let v = if negative { -v } else { v };
        return Ok(v as f32);
    }

    // Hexadecimal float.
    if rest.len() >= 2 && rest[..2].eq_ignore_ascii_case("0x") {
        if let Some((v, input_exact)) = parse_hex(&rest[2..]) {
            let v = if negative { -v } else { v };
            return range_check(v, input_exact);
        }
        // "0x" not followed by any hex digit: the valid prefix is just "0".
        return Ok(if negative { -0.0 } else { 0.0 });
    }

    // Decimal float.
    if let Some((len, sig_digits)) = scan_decimal(rest) {
        let v: f64 = rest[..len].parse().unwrap();
        let v = if negative { -v } else { v };
        // A nonzero f32 subnormal (k * 2^-149 = k * 5^149 * 10^-149) needs
        // 100+ significant decimal digits to be written exactly, so shorter
        // decimals in the subnormal range are always inexact.
        let input_exact = sig_digits >= 100;
        return range_check(v, input_exact);
    }

    Err(StofError::InvalidArgument)
}

/// Matches `inf` / `infinity` / `nan` prefixes, case-insensitive.
fn match_keyword(rest: &str) -> Option<f64> {
    let b = rest.as_bytes();
    if b.len() >= 8 && b[..8].eq_ignore_ascii_case(b"infinity") {
        return Some(f64::INFINITY);
    }
    if b.len() >= 3 && b[..3].eq_ignore_ascii_case(b"inf") {
        return Some(f64::INFINITY);
    }
    if b.len() >= 3 && b[..3].eq_ignore_ascii_case(b"nan") {
        return Some(f64::NAN);
    }
    None
}

/// Applies glibc's ERANGE rules to the parsed value `v` (f64 approximation of
/// the true value) and returns the correctly rounded f32.
/// `input_exact` means the input string may denote its value exactly (used to
/// spare exactly-representable subnormals from ERANGE).
fn range_check(v: f64, input_exact: bool) -> Result<f32, StofError> {
    let f = v as f32;
    // Overflow: rounds to infinity (hex may also overflow f64 itself).
    if f.is_infinite() {
        return Err(StofError::OutOfRange);
    }
    // Underflow to zero.
    if v != 0.0 && f == 0.0 {
        return Err(StofError::OutOfRange);
    }
    // Underflow into the subnormal range, unless exactly representable.
    if f.abs() < f32::MIN_POSITIVE {
        let exact = input_exact && (f as f64) == v;
        if !exact {
            return Err(StofError::OutOfRange);
        }
    }
    Ok(f)
}

/// Parses a hex float body (the part after `0x`): hex digits with an optional
/// '.', and an optional `p`/`P` binary exponent (consumed only if digits
/// follow). Returns (value as f64, input_exact), or None if there are no hex
/// digits at all.
fn parse_hex(rest: &str) -> Option<(f64, bool)> {
    let b = rest.as_bytes();
    let mut i = 0;
    let mut mantissa: u128 = 0;
    let mut any = false;
    let mut exact = true;
    let mut exp: i64 = 0; // binary exponent applied to the integer mantissa
    let mut seen_dot = false;
    while i < b.len() {
        let c = b[i];
        if c == b'.' && !seen_dot {
            seen_dot = true;
            i += 1;
            continue;
        }
        let d = match (c as char).to_digit(16) {
            Some(d) => d,
            None => break,
        };
        any = true;
        if mantissa <= (u128::MAX - 15) / 16 {
            if seen_dot {
                exp -= 4;
            }
            mantissa = mantissa * 16 + d as u128;
        } else {
            // Beyond u128 capacity: integer digits still scale the value,
            // fraction digits are dropped (inexact when nonzero).
            if !seen_dot {
                exp += 4;
            }
            if d != 0 {
                exact = false;
            }
        }
        i += 1;
    }
    if !any {
        return None;
    }
    // Optional binary exponent: p[+/-]digits.
    if i < b.len() && (b[i] == b'p' || b[i] == b'P') {
        let mut j = i + 1;
        let mut esign: i64 = 1;
        if j < b.len() && (b[j] == b'+' || b[j] == b'-') {
            if b[j] == b'-' {
                esign = -1;
            }
            j += 1;
        }
        let mut eval: i64 = 0;
        let mut edigits = 0;
        while j < b.len() && b[j].is_ascii_digit() {
            eval = (eval * 10 + (b[j] - b'0') as i64).min(1_000_000);
            j += 1;
            edigits += 1;
        }
        if edigits > 0 {
            exp += esign * eval;
        }
        // A bare 'p' with no digits is not part of the number.
    }
    if mantissa == 0 {
        return Some((0.0, true));
    }
    // More than 53 significant bits cannot be represented exactly in f64.
    let sig_bits = 128 - mantissa.leading_zeros() - mantissa.trailing_zeros();
    if sig_bits > 53 {
        exact = false;
    }
    let exp = exp.clamp(-2100, 2100);
    let v = (mantissa as f64) * 2f64.powi(exp as i32);
    if v == 0.0 {
        // Nonzero value below the f64 range: certainly an inexact underflow
        // for f32 as well. Report a tiny nonzero sentinel so range_check
        // takes the underflow path.
        return Some((f64::from_bits(1), false));
    }
    Some((v, exact))
}

/// Scans a decimal float prefix: digits with an optional '.', and an optional
/// `e`/`E` exponent (consumed only if digits follow). Returns (byte length of
/// the longest valid prefix, significant mantissa digit count), or None if
/// there are no mantissa digits at all.
fn scan_decimal(rest: &str) -> Option<(usize, usize)> {
    let b = rest.as_bytes();
    let mut i = 0;
    let mut int_digits = 0;
    while i < b.len() && b[i].is_ascii_digit() {
        i += 1;
        int_digits += 1;
    }
    let mut frac_digits = 0;
    if i < b.len() && b[i] == b'.' {
        let mut j = i + 1;
        while j < b.len() && b[j].is_ascii_digit() {
            j += 1;
            frac_digits += 1;
        }
        // The dot belongs to the number if either side has digits ("5.", ".5").
        if int_digits > 0 || frac_digits > 0 {
            i = j;
        }
    }
    if int_digits + frac_digits == 0 {
        return None;
    }
    // Significant digits: mantissa digits with leading zeros stripped.
    let mut sig = 0;
    let mut seen_nonzero = false;
    for &c in &b[..i] {
        if c == b'.' {
            continue;
        }
        if c != b'0' {
            seen_nonzero = true;
        }
        if seen_nonzero {
            sig += 1;
        }
    }
    // Optional exponent: e[+/-]digits, only if at least one digit follows.
    if i < b.len() && (b[i] == b'e' || b[i] == b'E') {
        let mut j = i + 1;
        if j < b.len() && (b[j] == b'+' || b[j] == b'-') {
            j += 1;
        }
        let mut edigits = 0;
        while j < b.len() && b[j].is_ascii_digit() {
            j += 1;
            edigits += 1;
        }
        if edigits > 0 {
            i = j;
        }
    }
    Some((i, sig))
}

