#[path = "src/lib.rs"]
mod color;

use color::converter::ColorConverter;
use color::fmt::format_g;
use color::rgb::RGB;
use color::stof::{stof, StofError};

/// Parses one argument with C++ `std::stof` semantics; on failure mimics the
/// uncaught-exception abort of the C++ runtime (SIGABRT, exit code 134).
fn parse_arg(s: &str) -> f32 {
    match stof(s) {
        Ok(v) => v,
        Err(e) => {
            let exception = match e {
                StofError::InvalidArgument => "std::invalid_argument",
                StofError::OutOfRange => "std::out_of_range",
            };
            eprintln!("terminate called after throwing an instance of '{}'", exception);
            eprintln!("  what():  stof");
            std::process::abort();
        }
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut r: f32 = 0.3;
    let mut g: f32 = 0.7;
    let mut b: f32 = 0.2;
    if args.len() > 3 {
        r = parse_arg(&args[1]);
        g = parse_arg(&args[2]);
        b = parse_arg(&args[3]);
    }
    let rgb = RGB::new(r, g, b);
    let inverted = ColorConverter::invert(rgb);
    let grayscale = ColorConverter::grayscale(rgb);
    println!(
        "{} {} {} {} {} {}",
        format_g(inverted.r),
        format_g(inverted.g),
        format_g(inverted.b),
        format_g(grayscale.r),
        format_g(grayscale.g),
        format_g(grayscale.b)
    );
}

